var Q1 = Class.create();
Q1.prototype = {
    initialize: function() {},

    fetchdetails: function(patid) {
        var gr = new GlideRecord("u_patient");
        gr.addQuery("u_number", patid);
        gr.query();

        if (gr.next()) {
            return {
                name: gr.getValue("u_first_name"),
                email: gr.getValue("u_email"),
                phone: gr.getValue("u_contact_number")
            };
        } else {
            return null;
        }
    },

    isVIP: function(vip) {


        var grs = new GlideRecord("u_patient");
        grs.addQuery("u_number", vip);
        grs.query();
        if (grs.next()) {
            return grs.getDisplayValue("u_vip")

        }
    },

    fetchappointment: function(apt) {
        var gra = new GlideRecord("u_appointment");
        gra.addQuery("u_patient_id.number", apt);
        gra.query();
        var results = [];
        while (gra.next()) {
            results.push({
				Date: gra.getValue("u_appointment_date"),
				Id: gra.getUniqueValue("number")})
        }
        return results;
    },

    type: 'Q1'
};
